/** North Texas Soccer Association official team roster.
 *  The paper (and the PDF print) looks like:
 *    2026 - 2027 North Texas Soccer Association Roster
 *    Van Soccer
 *    Van SA Hedgehogs
 *    Association: TXN   Season: Fall 2026   Age: U8
 *    Coach (Primary)  Last, First  Reg#  Phone  Email
 *    then a numbered kids table: Name / Jersey / Reg# / State / DOB / m/f / Status
 *  One PDF per team. Kids are imported from that table — never invented.
 */

import { inferYear } from "../dates";
import { norm, printName, teamLabel, type Child, type Family, type League, type Parent, type Team, type TeamAdult, type TeamPlayer } from "../model";
import { blankLeague } from "../parse";
import { fillPlanningHoles, normalizeBracket } from "../planning";
import { fillCrowFlies, missingPieceIssues, structuralRefusals } from "../validate";
import type { IntakeAttempt } from "./types";

export interface NtssaStaffRow {
  role: string;
  last: string;
  first: string;
  phone?: string;
  email?: string;
  reg?: string;
}

export interface NtssaKidRow {
  number: number;
  last: string;
  first: string;
  jersey?: string;
  reg?: string;
  state?: string;
  dob?: string;
  sex?: string;
  status?: string;
}

export interface NtssaRosterPage {
  club: string;
  teamRaw: string;
  team: string;
  bracket: string;
  gender: string;
  level: string;
  season: string;
  associationCode: string;
  teamNumber: string;
  staff: NtssaStaffRow[];
  kids: NtssaKidRow[];
}

const LABEL = /^(association|season|division|team number|age|gender|level|color)\s*:\s*(.*)$/i;
const STAFF_ROLE = /^(coach\s*\([^)]+\)|assistant(?:\s*coach)?|manager|team\s*manager|team\s*parent)\b/i;
const LAST_FIRST = /^([A-Za-z][A-Za-z'’.\-]*(?:\s+[A-Za-z][A-Za-z'’.\-]*)*),\s+([A-Za-z][A-Za-z'’.\-]*(?:\s+[A-Za-z][A-Za-z'’.\-]*)*)$/;
const KID_ROW =
  /^\s*(\d{1,2})\s+([A-Za-z][A-Za-z'’.\-]+(?:\s+[A-Za-z][A-Za-z'’.\-]+)*),\s+([A-Za-z][A-Za-z'’.\-]+(?:\s+[A-Za-z][A-Za-z'’.\-]+)*)\s+(?:(\d{1,3})\s+)?(\d{6,})\s+([A-Z]{2})\s+(\d{1,2}\/\d{4})\s+([MF])\s+([A-Z])\b/;
const STAFF_ROW =
  /^(coach\s*\([^)]+\)|assistant(?:\s*coach)?|manager|team\s*manager|team\s*parent)\s+([A-Za-z][A-Za-z'’.\-]+(?:\s+[A-Za-z][A-Za-z'’.\-]+)*),\s+([A-Za-z][A-Za-z'’.\-]+(?:\s+[A-Za-z][A-Za-z'’.\-]+)*)\s+(\d{4,})\s+(\+?\d{7,15})\s+(\S+@\S+)/i;
const HEADERISH = /^(role|name|jersey|reg#|phone|email|userid|state|dob|m\/f|status|assignment)/i;

export function looksLikeNtssaRoster(text: string): boolean {
  const t = text.replace(/\s+/g, " ");
  if (/north texas soccer association roster/i.test(t)) return true;
  return /coach\s*\(\s*primary\s*\)/i.test(t) && /\bage\s*:\s*u?\s*\d+/i.test(t);
}

function squash(line: string): string {
  return line.replace(/\s+/g, " ").trim();
}

function clubName(raw: string): string {
  const s = squash(raw);
  if (/^van soccer$/i.test(s) || /^vsa$/i.test(s) || /^van sa$/i.test(s)) return "Van Soccer Association";
  return s;
}

export function shortTeamName(raw: string): string {
  let s = squash(raw);
  s = s.replace(/^(van soccer association|van soccer|van sa|vsa)\s+/i, "");
  return s || squash(raw);
}

function bracketFromAge(age: string, gender: string): string {
  const n = normalizeBracket(age.trim());
  const g = gender.trim();
  if (/girl/i.test(g) && n && !/girl/i.test(n)) return `${n} Girls`;
  if (/boy/i.test(g) && n && !/boy/i.test(n) && !/coed/i.test(g)) return `${n} Boys`;
  return n || age.trim();
}

function parseLastFirst(raw: string): { last: string; first: string } | null {
  const m = squash(raw).match(LAST_FIRST);
  if (!m) return null;
  return { last: m[1], first: m[2] };
}

function parseKidLine(line: string): NtssaKidRow | null {
  const m = squash(line).match(KID_ROW);
  if (!m) return null;
  return {
    number: Number(m[1]),
    last: m[2],
    first: m[3],
    jersey: m[4] || undefined,
    reg: m[5],
    state: m[6],
    dob: m[7],
    sex: m[8],
    status: m[9],
  };
}

function parseStaffLine(line: string): NtssaStaffRow | null {
  const m = squash(line).match(STAFF_ROW);
  if (m) {
    return { role: m[1], last: m[2], first: m[3], reg: m[4], phone: m[5], email: m[6] };
  }
  const loose = squash(line).match(
    /^(coach\s*\([^)]+\)|assistant(?:\s*coach)?|manager|team\s*manager|team\s*parent)\s+(.+)$/i,
  );
  if (!loose) return null;
  const rest = loose[2];
  const nameHit = rest.match(/^([A-Za-z][A-Za-z'’.\-]+(?:\s+[A-Za-z][A-Za-z'’.\-]+)*),\s+([A-Za-z][A-Za-z'’.\-]+(?:\s+[A-Za-z][A-Za-z'’.\-]+)*)/);
  if (!nameHit) return null;
  const after = rest.slice(nameHit[0].length);
  const phone = after.match(/(\+?\d{7,15})/);
  const email = after.match(/(\S+@\S+)/);
  const reg = after.match(/\b(\d{4,})\b/);
  return {
    role: loose[1],
    last: nameHit[1],
    first: nameHit[2],
    phone: phone?.[1],
    email: email?.[1],
    reg: reg?.[1],
  };
}

export function parseNtssaRosterLines(lines: string[]): NtssaRosterPage | null {
  const cleaned = lines.map(squash).filter(Boolean);
  const blob = cleaned.join("\n");
  if (!looksLikeNtssaRoster(blob)) return null;

  const fields: Record<string, string> = {};
  let club = "";
  let teamRaw = "";
  const staff: NtssaStaffRow[] = [];
  const kids: NtssaKidRow[] = [];

  for (const line of cleaned) {
    const labeled = line.match(LABEL);
    if (labeled) {
      fields[labeled[1].toLowerCase()] = labeled[2].trim();
      continue;
    }
    if (HEADERISH.test(line) && !STAFF_ROLE.test(line) && !/^\d/.test(line)) continue;
    const kid = parseKidLine(line);
    if (kid) {
      kids.push(kid);
      continue;
    }
    const adult = parseStaffLine(line);
    if (adult) {
      staff.push(adult);
      continue;
    }
    if (/north texas soccer association roster/i.test(line)) continue;
    if (/north texas soccer$/i.test(line) || /^van soccer association$/i.test(line)) continue;
    if (/^van soccer$/i.test(line) && !club) {
      club = line;
      continue;
    }
    if (/^van sa\b/i.test(line) && !teamRaw) {
      teamRaw = line;
      continue;
    }
  }

  if (!teamRaw) {
    const named = cleaned.find((l) => /^van sa\b/i.test(l));
    if (named) teamRaw = named;
  }
  if (!club) {
    const named = cleaned.find((l) => /^van soccer$/i.test(l));
    if (named) club = named;
  }

  const age = fields.age || "";
  const gender = fields.gender || "";
  if (!teamRaw || !age || (!staff.length && !kids.length)) return null;

  return {
    club: clubName(club || "Van Soccer"),
    teamRaw,
    team: shortTeamName(teamRaw),
    bracket: bracketFromAge(age, gender),
    gender,
    level: fields.level || "",
    season: fields.season || "",
    associationCode: fields.association || "",
    teamNumber: fields["team number"] || "",
    staff,
    kids,
  };
}

function isAssistant(role: string): boolean {
  return /assistant|asst/i.test(role);
}

function adultFromStaff(row: NtssaStaffRow): TeamAdult {
  return { first: row.first, last: row.last, phone: row.phone };
}

function playerFromKid(row: NtssaKidRow): TeamPlayer {
  return {
    name: printName({ first: row.first, last: row.last }),
    jersey: row.jersey,
  };
}

export function teamFromNtssaPage(page: NtssaRosterPage): Team {
  const heads = page.staff.filter((s) => !isAssistant(s.role));
  const assts = page.staff.filter((s) => isAssistant(s.role));
  const coach = heads[0] ? adultFromStaff(heads[0]) : assts[0] ? adultFromStaff(assts[0]) : undefined;
  const assistant = heads[0] && assts[0] ? adultFromStaff(assts[0]) : heads[1] ? adultFromStaff(heads[1]) : undefined;
  return {
    name: page.team,
    bracket: page.bracket,
    association: page.club,
    jersey: "",
    coach,
    assistant,
    players: page.kids.map(playerFromKid),
    willNotPlay: [],
    willNotTravelTo: [],
    awayDesired: 0,
    guestDesired: 0,
  };
}

function ensureAgeGroup(league: League, bracket: string) {
  if (!bracket) return;
  if (league.ageGroups.some((a) => norm(a.name) === norm(bracket))) return;
  league.ageGroups.push({
    name: bracket,
    minOnField: null,
    maxOnField: null,
    gameLengthMinutes: null,
    assistantMin: null,
    assistantPreferred: null,
    fieldClasses: [],
    mayPlayWith: [bracket],
  });
}

function ensureClub(league: League, name: string) {
  if (!name) return;
  if (league.associations.some((a) => norm(a.name) === norm(name))) return;
  league.associations.push({
    name,
    controlled: /van soccer/i.test(name),
    homeCampus: /van soccer/i.test(name) ? "Van Complex" : undefined,
    guestSides: [],
  });
}

function lastNameOfPlayer(p: TeamPlayer): string {
  const parts = (p.name || "").trim().split(/\s+/);
  return parts.length > 1 ? parts[parts.length - 1] : parts[0] || "";
}

function familiesFromTeam(team: Team): Family[] {
  const byLast = new Map<string, Family>();
  const take = (last: string): Family => {
    const key = norm(last);
    let fam = byLast.get(key);
    if (!fam) {
      fam = { parents: [], children: [] };
      byLast.set(key, fam);
    }
    return fam;
  };
  if (team.coach?.last) {
    const fam = take(team.coach.last);
    if (!fam.parents.some((p) => norm(p.first) === norm(team.coach!.first) && norm(p.last) === norm(team.coach!.last))) {
      fam.parents.push({
        first: team.coach.first,
        last: team.coach.last,
        phone: team.coach.phone,
        coachOf: [teamLabel(team)],
        assistantOf: [],
      });
    }
  }
  if (team.assistant?.last) {
    const fam = take(team.assistant.last);
    if (!fam.parents.some((p) => norm(p.first) === norm(team.assistant!.first) && norm(p.last) === norm(team.assistant!.last))) {
      fam.parents.push({
        first: team.assistant.first,
        last: team.assistant.last,
        phone: team.assistant.phone,
        coachOf: [],
        assistantOf: [teamLabel(team)],
      });
    }
  }
  for (const kid of team.players) {
    const last = lastNameOfPlayer(kid);
    const first = (kid.name || "").replace(new RegExp(`\\s+${last.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`), "").trim() || kid.name;
    if (!last) continue;
    const fam = take(last);
    const child: Child = { first, last, bracket: team.bracket, team: team.name, jersey: kid.jersey };
    if (!fam.children.some((c) => norm(printName(c)) === norm(printName(child)))) fam.children.push(child);
  }
  return [...byLast.values()].filter((f) => f.children.length || f.parents.length);
}

export function upsertTeam(teams: Team[], next: Team) {
  const k = `${next.bracket} ${next.name}`.toLowerCase();
  const hit = teams.find((t) => `${t.bracket} ${t.name}`.toLowerCase() === k);
  if (!hit) {
    teams.push(next);
    return;
  }
  if (!hit.coach && next.coach) hit.coach = next.coach;
  if (next.coach?.phone && hit.coach && !hit.coach.phone) hit.coach.phone = next.coach.phone;
  if (!hit.assistant && next.assistant) hit.assistant = next.assistant;
  if (!hit.association && next.association) hit.association = next.association;
  for (const p of next.players) {
    if (p.name && !hit.players.some((x) => x.name.toLowerCase() === p.name.toLowerCase())) hit.players.push(p);
  }
}

export function mergeNtssaInto(league: League, page: NtssaRosterPage) {
  const team = teamFromNtssaPage(page);
  upsertTeam(league.teams, team);
  ensureAgeGroup(league, team.bracket);
  ensureClub(league, team.association);
  if (page.season && !league.season.title) {
    league.season.title = page.season;
    league.season.headerTitle = page.season;
  }
  if (/van soccer/i.test(page.club)) league.season.associationName = "Van Soccer Association";
  const year = inferYear(page.season || league.season.title, 2026);
  if (year && !league.season.headerTitle) league.season.headerTitle = `Fall ${year}`;
  for (const fam of familiesFromTeam(team)) {
    const key = fam.parents[0]?.last || fam.children[0]?.last || "";
    const existing = league.families.find(
      (f) =>
        (f.parents[0] && norm(f.parents[0].last) === norm(key)) ||
        (f.children[0] && norm(f.children[0].last) === norm(key)),
    );
    if (!existing) {
      league.families.push(fam);
      continue;
    }
    for (const p of fam.parents) {
      if (!existing.parents.some((x) => norm(printName(x)) === norm(printName(p)))) existing.parents.push(p);
      else {
        const hit = existing.parents.find((x) => norm(printName(x)) === norm(printName(p)))!;
        for (const c of p.coachOf) if (!hit.coachOf.includes(c)) hit.coachOf.push(c);
        for (const c of p.assistantOf) if (!hit.assistantOf.includes(c)) hit.assistantOf.push(c);
      }
    }
    for (const c of fam.children) {
      if (!existing.children.some((x) => norm(printName(x)) === norm(printName(c)) && x.team === c.team)) {
        existing.children.push(c);
      }
    }
  }
}

export function leagueFromNtssaPages(pages: NtssaRosterPage[], filename = ""): IntakeAttempt {
  if (!pages.length) return { matched: false, strategy: "ntssa-roster-pdf", reason: "no NTSSA roster pages" };
  const league = blankLeague();
  league.sourceName = filename || undefined;
  league.sampleOnly = false;
  const report: string[] = [];
  for (const page of pages) {
    mergeNtssaInto(league, page);
    report.push(`${page.bracket} ${page.team}: ${page.kids.length} kids from the NTSSA roster`);
  }
  fillPlanningHoles(league);
  league.travel = fillCrowFlies(league);
  const issues = [
    ...structuralRefusals(league)
      .filter((i) => i.code === "age-group-incomplete" || i.code === "leftover-sample")
      .map((i) => ({ ...i, level: "flag" as const })),
    ...missingPieceIssues(league),
  ];
  report.push(`NTSSA team PDFs: ${league.teams.length} team${league.teams.length === 1 ? "" : "s"}, ${league.teams.reduce((n, t) => n + t.players.length, 0)} named kids`);
  const hard = structuralRefusals(league).filter((i) => i.code !== "age-group-incomplete" && i.code !== "leftover-sample");
  if (hard.length) {
    return {
      matched: true,
      strategy: "ntssa-roster-pdf",
      result: { ok: false, league, issues: [...issues, ...hard], report, strategy: "ntssa-roster-pdf" },
    };
  }
  return {
    matched: true,
    strategy: "ntssa-roster-pdf",
    result: { ok: true, league, issues, report, strategy: "ntssa-roster-pdf" },
  };
}

export function tryNtssaRosterText(text: string, filename = ""): IntakeAttempt {
  const page = parseNtssaRosterLines(text.split(/\r?\n/));
  if (!page) return { matched: false, strategy: "ntssa-roster-pdf", reason: "not an NTSSA team roster" };
  return leagueFromNtssaPages([page], filename);
}

export { type Parent };
